# -*- coding: utf-8 -*-
"""W3 stage1-a: d1 全部 6 条 + d2 全部 6 条"""
import json

S = {}

S['w3d1-p1'] = {'topic': 'Python 解释器与执行方式', 'desc':
'Python 是解释型语言，你写的 .py 文件本质是纯文本，机器看不懂，必须有一层"翻译官"——解释器（CPython 就是官方那个）逐行读、逐行译成机器码再执行。这决定了三件你以后天天要面对的事：第一，源码是文本，改一个字符马上生效，不需要编译步骤，所以 Python 的迭代速度极快，代价是运行速度比 C 慢一到两个数量级；第二，报错分两阶段——解释器读文件时先做语法解析，缩进错了、括号没闭、冒号漏了，这时抛 SyntaxError，程序一行都没跑；语法过了才开始执行，此时抛的 TypeError、NameError、IndexError 才是"跑起来了才出事"。判断报错该怪谁，看异常类型就能分：SyntaxError/IndentationError 是"没进门"，其余是"进门口摔了"。第三，解释器本身是个可执行程序，pycharm 也好、VS Code 也好，它们只是壳，真正干活的是 python3 这个二进制。'
}

S['w3d1-p2'] = {'topic': '环境安装与 Python 3 版本确认', 'desc':
'装机三条路：①官方 installer（python.org）或系统包管理器 apt install python3，装到系统全局，适合只为跑个脚本；②pyenv 管理多版本并存，适合需要切 3.8/3.10/3.12 的场景；③venv 建虚拟环境——注意 venv 不安装新解释器，它只复制一份指向系统解释器的软链，然后给你一个独立的 site-packages 目录，解决"项目 A 要 requests 2.28、项目 B 要 3.0"的冲突。确认自己到底在跑哪个 Python，三条命令必须都会：python3 --version 看版本号；which python3（Windows 用 where python）看可执行文件路径；在代码里 import sys 然后 print(sys.executable)，这是唯一能确认"当前这个解释器是谁"的办法，IDE 里配错解释器时全靠它。两个高频坑：Windows 装了 Python 却没勾 Add to PATH，命令行敲 python 会弹出微软商店；系统里 python 和 python3 可能是两个不同版本，一律用 python3 起步，装包一律用 python3 -m pip install 而不是直接 pip，这样能保证包装进的是同一个解释器。'
}

S['w3d1-p3'] = {'topic': '第一个程序 hello.py 与 print', 'desc':
'建一个 hello.py（扩展名必须是 .py，不是 .txt），内容一行 print 加一对圆括号，括号里放你要输出的东西，字符串用单引号或双引号包住都行。终端里 cd 到文件所在目录，python3 hello.py 回车，屏幕吐出那行字——这一步跑通的意义不是"我会编程了"，而是把"写文件 → 保存 → 定位目录 → 调解释器 → 看输出"这条完整回路打通，后面所有报错排查都依赖这条回路清晰。print 的三个常用细节：多个参数用逗号分隔时，print 会自动补一个空格；print 默认结尾换行，加 end= 空字符串可以取消换行，做进度条或同行输出时要用；print 是函数不是语句，所以 print 后面不加括号在 Python 3 里不会输出，只会返回函数对象。如果敲 python3 hello.py 报 can not open file，先查文件名是不是 hello.py.txt（Windows 隐藏扩展名坑），再查当前目录对不对（pwd / cd 看一眼）。'
}

S['w3d1-p4'] = {'topic': '缩进即语法块', 'desc':
'Python 用缩进代替大括号表示代码归属，这是它唯一的"块语法"。规则只有一条但必须刻进肌肉记忆：同一个代码块内的行，缩进必须完全一致，而且空格和 Tab 绝对不能混用。推荐统一 4 个空格，编辑器里设定"Tab 键插入 4 个空格"。缩进错会得到两种报错：IndentationError: expected an indented block——该缩进的地方（if、for、while、def 后面那行）没缩进；IndentationError: unexpected indent——不该缩进的地方多缩进了，通常是复制粘贴带进来的空格。还有一种最难查的：TabError: inconsistent use of tabs and spaces in indentation，肉眼看起来一模一样，但一个字符是 \t、一个是四个空格，解释器认为不对齐。解决办法是打开编辑器的"显示空白字符"功能，一眼看出痕迹，然后全文件统一替换成空格。判断某行属于哪个块，就看它缩进和上面哪个冒号行对齐，缩进层级本身就是程序的逻辑结构。'
}

S['w3d1-p5'] = {'topic': '注释与代码可读性', 'desc':
'注释两种：# 后面到行尾都是注释，用于解释"这行为什么这么写"；三引号包起来的是多行字符串，放在函数或文件开头时会被当作 docstring（文档字符串），IDE 悬停提示和 help() 读的就是它。写注释的铁律：解释"为什么"，不复述"做了什么"——`i = i + 1  # i 加一`这种注释等于没写，纯噪音；`i += 1  # 跳过表头行`才是有信息量的。三条实用规范：①每个函数开头用 docstring 写一句目的 + 参数 + 返回值，写的时候逼自己想清楚职责，写着写着发现说不清楚，说明这个函数该拆了；②注释掉的旧代码直接删，不要留着"万一以后要用"，git 已经帮你记着了；③复杂表达式的中间变量名就是最好的注释，把 `d[k1][k2].get(x, 0) + 1` 拆成 `row = d[k1][k2]; cnt = row.get(x, 0)`，可读性直接翻倍。调试期临时注释掉代码用 #，但提交前必须清理干净。'
}

S['w3d1-p6'] = {'topic': '报错的读法', 'desc':
'Python 报错信息是一个三段式结构，从下往上读。最后一行是错误类型 + 错误消息，例如 TypeError: unsupported operand type(s) for +: int and str，这句话本身就说明了病因——数字和字符串相加，一看就懂，先读这行能解决七成问题。倒数第二部分是出错的具体代码行，会显示文件名、行号和那一行原文，直接告诉你现场在哪。最上面那一大段是调用栈（Traceback），从最外层函数一路调到最后出错的位置，函数一层套一层时，最下面是"死在哪"，最上面是"从哪进去的"。读法训练要点：①先看异常类型决定去哪类问题里找——NameError 拼错变量名、KeyError 字典没这个键、IndexError 下标越界、AttributeError 对象没这个属性、ModuleNotFoundError 包没装或装错解释器；②找到行号后不要只看那一行，要往上看这个变量的值从哪来的；③报错信息是英文的，看不懂就整句复制去搜，不要自己瞎猜关键词。养成习惯：报错不慌，先读完最后一行，再读行号，再往回溯源。'
}

S['w3d2-p1'] = {'topic': '变量是名字不是盒子', 'desc':
'最要命的误解是把变量想成"装数据的盒子"——盒子有容量、赋值就是往里塞东西。Python 的真实模型是：内存里有一个对象，变量只是一张贴在对象上的标签（名字指向对象）。`a = [1, 2, 3]` 干的事是先在堆上建一个列表对象，再让名字 a 指向它；`b = a` 不是复制列表，而是给同一个对象再贴一张标签 b。所以 `b.append(4)` 之后 a 也会变成 [1, 2, 3, 4]——它们压根就是同一个东西。这个模型推导出三条必考的结论：①`is` 判断的是"是不是同一个对象"（比 id），`==` 判断的是"值是否相等"，两个内容相同的列表 `==` 为 True 但 `is` 为 False；②函数传参传的是引用（对象地址），在函数里对列表做 append/sort/赋值元素，会影响外面的列表，想让外面不变必须传副本；③不可变对象（int、str、tuple）没有"原地修改"这回事，`x += 1` 实际是新建一个整数对象再让 x 指向它——这也是为什么字符串拼接在大循环里很慢，每次都在造新对象。判断有没有被共享，用 id(对象) 打印一下地址最直接。'
}

S['w3d2-p2'] = {'topic': '动态类型与 type 检查', 'desc':
'Python 是动态类型语言：变量本身没有类型，类型属于它指向的那个对象，赋什么值这个变量就指向什么类型的对象，同一个名字可以在不同时刻指向不同类型——`x = 1` 之后 `x = "hello"` 完全合法，这在 C/Java 里是非法的。用 type(对象) 能看到真实类型，isinstance(对象, 类型) 判断"是不是这一类"（推荐用 isinstance，它能兼容继承关系，type 是精确匹配，对 bool 和 int 这种子类关系会出意外）。动态类型带来的便利是不用提前声明，代价是类型错误只能在运行时暴露——`"1" + 1` 要到执行那一行才炸。所以处理外部输入（input、读文件、爬来的 JSON）时必须显式转换：int()、float()、str()、bool()。bool() 有个大坑：bool("False") 是 True，因为非空字符串都算真，字符串转布尔不看内容。int() 转浮点字符串会抛 ValueError，要转 financial 数值先 float 再 round，别指望 int 一步到位。'
}

S['w3d2-p3'] = {'topic': '变量命名规则与约定', 'desc':
'硬规则（违反直接报 SyntaxError）：只能用字母、数字、下划线，不能以数字开头，不能用关键字（if、for、class、None、True 等，用 import keyword; print(keyword.kwlist) 能列全），大小写敏感（age 和 Age 是两个变量）。软约定（违反不报错但会被同事骂）：函数和变量用下划线命名 get_user_name，类用大驼峰 UserProfile，常量全大写 MAX_RETRY；不要用 l、O、I 这种单字母（极易和 1、0 混）；不要用拼音缩写（yh、xm 这种三天后自己都看不懂）；不要遮蔽内置名 list、dict、str、type、id、sum——遮蔽之后你再想用原来的功能就得难受。命名本身是设计行为：user_list 比 data 好，pending_orders 比 tmp 好。一个判据——如果你起名卡住了，往往说明这段变量承担了多个职责，该拆了。'
}

S['w3d2-p4'] = {'topic': 'input 输入与类型转换', 'desc':
'input() 永远返回字符串，没有例外。所以 `age = input("年龄：")` 拿到的是 "18" 而不是 18，直接 `age > 18` 会抛 TypeError（字符串和整数不能比大小）。正确写法是拿到字符串立刻转换：`age = int(input("年龄："))`。转换必须考虑失败情形——用户输入"十八"或者直接回车，int() 抛 ValueError，程序当场崩。健壮写法是包一层循环加 try：把转换放在 try 里，except ValueError 就提示"请输入数字"然后重新输入，直到成功为止。三个具体点：①数值输入用 int() 还是 float() 取决于业务，价格、成绩这类一律 float；②input 的提示串最好在末尾带空格和冒号，否则用户光标贴着文字；③多个值逗号输入要 `parts = input().split(",")` 再逐个 strip() 转换，split 的结果一定要去空格，否则 "1, 2" 转 int 会失败。'
}

S['w3d2-p5'] = {'topic': 'f-string 格式化', 'desc':
'f-string 是 Python 3.6+ 的字符串格式化首选写法：在引号前加 f，字符串里用大括号塞变量或表达式，例如 f"{name} 今年 {age} 岁"。大括号里可以放任何表达式——算术、函数调用、甚至三目运算，都可以，所以 f"{price * qty:.2f}" 一步到位完成乘法和格式化。格式说明符写在冒号后面：`.2f` 保留两位小数（会四舍五入）、`,.2f` 千分位加两位小数（做金额显示必备）、`>10` 右对齐占 10 宽、`<10` 左对齐、`^10` 居中、`05d` 补零到 5 位、`%` 转百分比、`:.1%` 一位小数的百分比。对齐补位组合 `{name:<10}{score:>6.1f}` 是做控制台表格的利器。两个坑：f-string 里想输出字面大括号要写双大括号 `{{}}`；引号嵌套时，外层和里层不能用同一个引号（Python 3.12 之前），常见做法是外层单引号内层双引号，或者把内层字符串提前赋给变量。'
}

S['w3d2-p6'] = {'topic': '数值运算与浮点误差', 'desc':
'运算符全表：`+ - * /`，`//` 是整除（向下取整，注意 -7 // 2 = -4 不是 -3）、`%` 取余（负数取余结果符号跟除数走）、`**` 幂运算、`+= -= *= /=` 复合赋值。浮点数有一个必须知道的先天缺陷：二进制无法精确表示 0.1 这类十进制小数，所以 `0.1 + 0.2 == 0.3` 结果是 False，实际值约等于 0.30000000000000004。这条推论影响三处代码写法：①任何浮点数相等比较都不能用 ==，要用 `abs(a - b) < 1e-9` 或者用 math.isclose(a, b)；②涉及金额的计算不要用 float，要用整数存"分"（把 12.34 存成 1234）或者用 decimal.Decimal("12.34") 并配合 ROUND_HALF_UP 控制舍入；③显示时统一 `:.2f` 收口，不要裸 print 浮点数给用户看。除法永远返回 float（`6 / 2` 是 3.0），要整数用 `//`。大整数 Python 没有溢出问题（任意精度），但超大整数的运算会慢，这不影响日常脚本。'
}

json.dump(S, open('/tmp/w3_s1a.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('COUNT', len(S))
